def js(x): return json.dumps(x,ensure_ascii=False,separators=(',',':'))
html=r'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b6b45"><title>ごみナビ｜恵那市 × 中津川市</title><style>
:root{--bg:#f4f7f5;--card:#fff;--text:#15231c;--muted:#647269;--line:#d8e2dc;--accent:#0b6b45;--accent2:#e6f3ec;--warn:#9a5b00;--warnbg:#fff4d9;--danger:#a02c2c;--dangerbg:#fff0ef;--blue:#215a8b;--shadow:0 8px 24px rgba(20,45,31,.08)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Hiragino Sans","Yu Gothic",Meiryo,sans-serif}.wrap{max-width:1080px;margin:auto;padding:14px 14px 80px}.header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 2px}.brand{font-size:24px;font-weight:900}.sub{font-size:12px;color:var(--muted)}button,input,select{font:inherit}.nav{position:sticky;top:0;z-index:20;background:rgba(244,247,245,.94);backdrop-filter:blur(10px);display:flex;gap:7px;padding:8px 0;overflow:auto}.nav button{white-space:nowrap;border:1px solid var(--line);background:white;border-radius:999px;padding:10px 13px;font-weight:700}.nav button.active{background:var(--accent);color:white;border-color:var(--accent)}.panel{display:none}.panel.active{display:block}.hero{background:var(--card);border:1px solid var(--line);border-radius:22px;padding:18px;box-shadow:var(--shadow)}.hero-top{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.hero select{border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:white;font-weight:700}.search{display:flex;gap:8px;margin-top:14px}.search input{flex:1;min-width:0;border:2px solid var(--accent);border-radius:15px;padding:15px 14px;font-size:17px}.primary{border:0;background:var(--accent);color:white;border-radius:13px;padding:11px 16px;font-weight:800;cursor:pointer}.secondary{border:1px solid var(--line);background:#fff;color:var(--text);border-radius:12px;padding:9px 12px;font-weight:700;cursor:pointer}.quick,.filters,.tags,.actions{display:flex;gap:7px;flex-wrap:wrap}.quick{margin-top:10px}.quick button,.chip{border:1px solid var(--line);background:white;border-radius:999px;padding:7px 10px;cursor:pointer}.chip.active{background:var(--accent);color:white}.trust{margin-top:12px;display:flex;gap:8px;flex-wrap:wrap}.badge{display:inline-flex;align-items:center;gap:4px;border-radius:999px;background:var(--accent2);padding:6px 9px;font-size:12px;font-weight:700}.badge.gray{background:#eef1ef}.badge.warn{background:var(--warnbg);color:var(--warn)}.section{margin-top:18px}.section-title{display:flex;justify-content:space-between;align-items:end;gap:10px;margin:0 0 10px}.section-title h2{font-size:18px;margin:0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.card{background:white;border:1px solid var(--line);border-radius:17px;padding:15px}.result-card{border-top:5px solid var(--accent)}.result-name{font-size:20px;font-weight:900;margin-bottom:7px}.category{display:inline-block;background:var(--accent2);border-radius:9px;padding:5px 8px;font-size:13px;font-weight:800}.instructions{line-height:1.7;margin-top:10px}.decision{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:13px}.decision>div{border:1px solid var(--line);border-radius:13px;padding:11px;background:#fafcfb}.decision strong{display:block;margin-bottom:5px}.danger{border:1px solid #efc2be;background:var(--dangerbg);color:#671b19;border-radius:14px;padding:12px;margin-top:11px}.facility{position:relative}.facility h3{margin:0 0 6px;font-size:17px}.facility .type{font-size:12px;color:var(--muted)}.tag{font-size:12px;background:#f0f3f1;border-radius:999px;padding:5px 8px}.meta{font-size:12px;color:var(--muted);line-height:1.5;margin-top:10px}.actions{margin-top:11px}.actions a,.actions button{border:1px solid var(--line);background:white;color:var(--accent);text-decoration:none;border-radius:10px;padding:8px 10px;font-weight:700;cursor:pointer}.actions a.route{background:var(--accent);color:white;border-color:var(--accent)}.contact{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center}.phone{font-size:20px;font-weight:900}.contact a{background:var(--accent);color:white;padding:10px 13px;border-radius:11px;text-decoration:none;font-weight:800}.notice{padding:13px;border:1px solid var(--line);border-radius:14px;background:white;line-height:1.65}.calendar-card{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}.calendar-card a{background:var(--accent);color:white;text-decoration:none;padding:10px 13px;border-radius:11px;font-weight:800}.toggle-row{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.empty{text-align:center;padding:28px;color:var(--muted)}.small{font-size:13px;color:var(--muted);line-height:1.6}.report-box{margin-top:12px;border-top:1px dashed var(--line);padding-top:10px}.foot{font-size:12px;color:var(--muted);line-height:1.7;margin-top:24px}.locationStatus{font-size:13px;color:var(--muted)}@media(max-width:760px){.wrap{padding:10px 10px 70px}.brand{font-size:22px}.grid{grid-template-columns:1fr}.decision{grid-template-columns:1fr}.hero{padding:14px;border-radius:17px}.search input{font-size:16px}.search .primary{padding:10px 12px}.contact,.calendar-card{grid-template-columns:1fr}.phone{font-size:18px}}
</style></head><body><div class="wrap"><header class="header"><div><div class="brand">♻️ ごみナビ</div><div class="sub">恵那市 × 中津川市｜公式資料＋民間公式回収情報</div></div><div class="sub" id="count"></div></header><nav class="nav"><button class="active" data-tab="search">🔎 品目検索</button><button data-tab="places">📍 回収場所</button><button data-tab="calendar">📅 収集日</button><button data-tab="contact">☎ 問い合わせ</button><button data-tab="latest">✓ 最新情報</button></nav>
<section id="panel-search" class="panel active"><div class="hero"><div class="hero-top"><strong>お住まいの市</strong><select id="city"><option value="ena">恵那市</option><option value="nakatsugawa">中津川市</option></select><span class="locationStatus" id="locStatus">現在地は未使用</span><button class="secondary" id="useLocation">現在地を使う</button></div><div class="search"><input id="q" placeholder="何を捨てたいですか？ 例：電池、布団、段ボール" aria-label="品目検索"><button class="primary" id="searchBtn">検索</button></div><div class="quick" id="quick"></div><div class="trust"><span class="badge">✓ 公式品目データ</span><span class="badge gray" id="fresh"></span><span class="badge gray" id="placeCount"></span></div></div><div class="filters" id="categoryFilters" style="margin-top:12px"></div><div class="section"><div class="section-title"><h2 id="resultTitle">よく使う品目</h2><span class="small" id="resultCount"></span></div><div class="grid" id="results"></div></div></section>
<section id="panel-places" class="panel"><div class="hero"><div class="hero-top"><strong>回収場所を探す</strong><select id="facilityCity"><option value="ena">恵那市</option><option value="nakatsugawa">中津川市</option></select><button class="secondary" id="placeLocation">現在地からルート</button></div><div class="search"><input id="facilityQ" placeholder="回収品目・施設名 例：段ボール、電池、古着"><button class="primary" id="facilityBtn">検索</button></div><div class="toggle-row"><button class="chip active" data-place-filter="all">すべて</button><button class="chip" data-place-filter="private">民間</button><button class="chip" data-place-filter="public">自治体</button><button class="chip" data-place-filter="24h">24時間</button></div><div class="small">「現在地から行く」はGoogleマップを開き、許可された現在地から目的地までのルートを表示します。</div></div><div class="section"><div class="section-title"><h2>回収・持込場所</h2><span class="small" id="facilityCount"></span></div><div class="grid" id="facilities"></div></div></section>
<section id="panel-calendar" class="panel"><div class="section"><div class="card calendar-card"><div><h2 style="margin:0 0 7px">恵那市 令和8年度ごみ収集</h2><div class="small">可燃：大井・長島・東野・武並・笠置・中野方・飯地＝月・木。三郷・岩村・山岡・明智・串原・上矢作＝火・金。資源・不燃・処理困難は地区別カレンダーで確認してください。</div></div><a href="https://www.city.ena.lg.jp/soshikiichiran/suidokankyobu/kankyoka/1/3/2/1745.html" target="_blank">公式カレンダー</a></div><div class="card calendar-card" style="margin-top:12px"><div><h2 style="margin:0 0 7px">中津川市 令和8年度 地区別収集日</h2><div class="small">市公式の地区別検索に直接つなぎます。地区名から燃えるごみ・燃えないごみ・資源などの日程を確認できます。</div></div><a href="https://www.city.nakatsugawa.lg.jp/garbage_search/chikubetsu/index.html" target="_blank">地区別検索</a></div></div></section>
<section id="panel-contact" class="panel"><div class="grid"><div class="card contact"><div><div class="small">恵那市のごみについて</div><strong>恵那市 環境課 環境係</strong><div class="phone">0573-26-6847</div><div class="small">平日 8:30〜17:15</div></div><a href="tel:0573266847">電話する</a></div><div class="card contact"><div><div class="small">中津川市のごみについて</div><strong>中津川市 環境センター</strong><div class="phone">0573-62-0085</div><div class="small">ごみ処理・収集・資源化</div></div><a href="tel:0573620085">電話する</a></div></div><div class="notice" style="margin-top:12px"><strong>迷ったとき</strong><br>リチウムイオン電池、スプレー缶、薬品、消火器、家電4品目など、事故や法令に関わる可能性がある品目は自己判断せず、検索結果の公式資料または上記窓口で確認してください。</div></section>
<section id="panel-latest" class="panel"><div id="latestCards" class="grid"></div><div class="notice" style="margin-top:12px"><strong>情報鮮度の扱い</strong><br>品目は自治体公式マニュアルを基礎にし、回収場所は自治体または事業者の公式ページで確認した情報を掲載しています。「確認日」と「情報源」を各カードに表示します。民間回収は営業時間・回収内容が変更されることがあるため、訪問前に公式情報を確認してください。</div></section>
<footer class="foot">自治体公式サービスではありません。掲載内容は検索しやすく再構成したものです。危険物・処理困難物・料金・臨時休業は必ずリンク先の最新公式情報を優先してください。</footer></div><script>
const ITEMS=__ITEMS__,FACILITIES=__FAC__,META=__META__;const dangerous=['リチウム','モバイルバッテリー','充電池','スプレー','ガスボンベ','ガス缶','ライター','消火器','薬品','農薬','水銀','バッテリー'];let activeCategory='all',placeFilter='all',userPos=null;const $=id=>document.getElementById(id);function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function norm(s){return String(s||'').toLowerCase().replace(/[\s　・･（）()\-ー]/g,'')}function cName(c){return c==='ena'?'恵那市':'中津川市'}function cityItems(){return ITEMS.filter(x=>x.city===$('city').value)}function routeUrl(f){let u='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(f.address);if(userPos)u+='&origin='+userPos.lat+','+userPos.lng;return u+'&travelmode=driving'}function searchMap(f){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(f.address)}function isDanger(item){let t=norm(item.name+' '+item.instructions);return dangerous.some(x=>t.includes(norm(x)))}function itemFacilities(item){let t=norm(item.name+' '+item.category+' '+item.instructions);return FACILITIES.filter(f=>f.city===item.city&&(f.accepted||[]).some(a=>t.includes(norm(a))||norm(a).includes(norm(item.name)))).slice(0,8)}function useGeo(){if(!navigator.geolocation){$('locStatus').textContent='位置情報非対応';return} $('locStatus').textContent='現在地を取得中…';navigator.geolocation.getCurrentPosition(p=>{userPos={lat:p.coords.latitude,lng:p.coords.longitude};$('locStatus').textContent='✓ 現在地をルートに使用';},()=>{$('locStatus').textContent='位置情報を取得できませんでした';},{enableHighAccuracy:false,timeout:8000})}
function renderQuick(){let w=['電池','モバイルバッテリー','フライパン','布団','テレビ','段ボール'];$('quick').innerHTML='';w.forEach(x=>{let b=document.createElement('button');b.textContent=x;b.onclick=()=>{$('q').value=x;doSearch()};$('quick').appendChild(b)})}function renderFilters(){let cats=[...new Set(cityItems().map(x=>x.category))].sort();$('categoryFilters').innerHTML='';[['all','すべて'],...cats.map(x=>[x,x])].forEach(([v,l])=>{let b=document.createElement('button');b.className='chip'+(activeCategory===v?' active':'');b.textContent=l;b.onclick=()=>{activeCategory=v;renderFilters();doSearch()};$('categoryFilters').appendChild(b)})}
function itemCard(item,term){let fs=itemFacilities(item),danger=isDanger(item),contact=META[item.city].contact;return `<article class="card result-card"><div class="result-name">${esc(item.name)}</div><span class="category">${esc(item.category)}</span>${item.large_sticker?` <span class="badge gray">大型シール ${esc(item.large_sticker)}</span>`:''}${danger?`<div class="danger"><strong>⚠️ 注意が必要な品目です</strong><br>発火・破裂・有害性などの可能性があります。公式の注意事項を優先し、迷ったら自治体へ問い合わせてください。</div>`:''}<div class="instructions">${esc(item.instructions)||'公式資料に追加説明はありません。'}</div><div class="decision"><div><strong>① 市の収集</strong><span class="small">${esc(item.category)}として出す。地区別の収集日を確認。</span></div><div><strong>② 持ち込む・回収</strong><span class="small">${fs.length?`${fs.length}件の候補があります。`:'登録済み回収拠点との一致なし。'}</span></div><div><strong>③ 迷ったら</strong><span class="small">${esc(contact.name)}<br>${esc(contact.phone)}</span></div></div>${fs.length?`<div class="tags" style="margin-top:10px">${fs.slice(0,4).map(f=>`<span class="tag">${esc(f.name)}</span>`).join('')}</div>`:''}<div class="actions"><a href="${item.source_url}" target="_blank">公式品目資料</a><a href="${contact.calendar}" target="_blank">収集日</a>${fs.length?`<button class="goPlaces" data-q="${esc(item.name)}" data-city="${item.city}">回収場所を見る</button>`:''}<a href="tel:${contact.phone.replace(/-/g,'')}">自治体に電話</a></div><div class="meta">公式資料 p.${esc(item.source_page)}｜確認 ${esc(item.verified_at)}</div></article>`}
function doSearch(){let term=$('q').value.trim(),arr=cityItems();if(activeCategory!=='all')arr=arr.filter(x=>x.category===activeCategory);if(term){let n=norm(term);arr=arr.filter(x=>norm(x.name).includes(n)||norm(x.instructions).includes(n)||norm(x.category).includes(n));$('resultTitle').textContent=`「${term}」の検索結果`}else{let fav=['電池','布団','テレビ','フライパン','段ボール','ペットボトル'];arr=arr.filter(x=>fav.some(f=>x.name.includes(f))).slice(0,12);$('resultTitle').textContent='よく使う品目'}arr=arr.slice(0,80);$('resultCount').textContent=arr.length+'件';$('results').innerHTML=arr.length?arr.map(x=>itemCard(x,term)).join(''):'<div class="card empty">見つかりません。品名を短くして検索してください。</div>';document.querySelectorAll('.goPlaces').forEach(b=>b.onclick=()=>{switchTab('places');$('facilityCity').value=b.dataset.city;$('facilityQ').value=b.dataset.q;renderFacilities()})}
function facilityCard(f){let current=f.hours_mode==='24h'?'<span class="badge">24時間</span>':'';let phone=f.phone?`<a href="tel:${f.phone.replace(/[^0-9]/g,'')}">電話</a>`:'';return `<article class="card facility"><div class="type">${esc(f.operator||'')}・${esc(f.type)}</div><h3>${esc(f.name)}</h3>${current}<div class="instructions"><strong>所在地</strong><br>${esc(f.address)}<br><strong>利用時間</strong><br>${esc(f.hours)}<br><strong>料金</strong><br>${esc(f.fee||'要確認')}</div><div class="tags" style="margin-top:9px">${(f.accepted||[]).slice(0,10).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>${f.notes?`<div class="small" style="margin-top:8px">${esc(f.notes)}</div>`:''}<div class="actions"><a class="route" href="${routeUrl(f)}" target="_blank">現在地から行く</a><a href="${searchMap(f)}" target="_blank">地図</a>${phone}<a href="${f.source_url}" target="_blank">公式情報</a></div><div class="meta">${esc(f.source_kind)}｜確認 ${esc(f.verified_at)}｜信頼度：公式確認済み</div><div class="report-box small">情報が違う場合：公式情報を確認後、自治体または店舗へお問い合わせください。</div></article>`}
function renderFacilities(){let c=$('facilityCity').value,n=norm($('facilityQ').value.trim()),arr=FACILITIES.filter(f=>f.city===c);if(n)arr=arr.filter(f=>norm(f.name+' '+f.type+' '+f.operator+' '+(f.accepted||[]).join(' ')).includes(n));if(placeFilter==='private')arr=arr.filter(f=>(f.operator||'自治体')!=='自治体');if(placeFilter==='public')arr=arr.filter(f=>(f.operator||'自治体')==='自治体');if(placeFilter==='24h')arr=arr.filter(f=>f.hours_mode==='24h'||String(f.hours).includes('24時間'));arr.sort((a,b)=>(b.hours_mode==='24h')-(a.hours_mode==='24h')||a.name.localeCompare(b.name,'ja'));$('facilityCount').textContent=`${arr.length}件`;$('facilities').innerHTML=arr.length?arr.map(facilityCard).join(''):'<div class="card empty">該当する回収場所がありません。</div>'}
function switchTab(t){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));$('panel-'+t).classList.add('active');if(t==='places')renderFacilities()}function renderLatest(){$('latestCards').innerHTML=['ena','nakatsugawa'].map(c=>{let m=META[c];return `<div class="card"><h2 style="margin-top:0">${cName(c)}</h2><span class="badge">✓ 公式情報確認済み</span><p class="small">公式ページ更新：<strong>${esc(m.official_page_updated)}</strong><br>アプリデータ確認：<strong>2026-08-13</strong><br>品目資料：${esc(m.manual_title||m.guide_title)}</p><div class="actions"><a href="${m.official_page_url}" target="_blank">最新公式ページ</a><a href="${m.manual_url||m.guide_url}" target="_blank">品目資料</a></div></div>`}).join('')}

document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('city').onchange=()=>{activeCategory='all';$('facilityCity').value=$('city').value;updateSummary();renderFilters();doSearch()};$('facilityCity').onchange=renderFacilities;$('searchBtn').onclick=doSearch;$('q').onkeydown=e=>{if(e.key==='Enter')doSearch()};$('facilityBtn').onclick=renderFacilities;$('facilityQ').onkeydown=e=>{if(e.key==='Enter')renderFacilities()};$('useLocation').onclick=useGeo;$('placeLocation').onclick=useGeo;document.querySelectorAll('[data-place-filter]').forEach(b=>b.onclick=()=>{placeFilter=b.dataset.placeFilter;document.querySelectorAll('[data-place-filter]').forEach(x=>x.classList.toggle('active',x===b));renderFacilities()});function updateSummary(){let c=$('city').value,m=META[c];$('fresh').textContent='公式ページ更新 '+m.official_page_updated;$('placeCount').textContent='回収場所 '+FACILITIES.filter(f=>f.city===c).length+'件'}$('count').textContent=`品目 ${ITEMS.length.toLocaleString()}件／回収場所 ${FACILITIES.length}件`;renderQuick();updateSummary();renderFilters();doSearch();renderFacilities();renderLatest();
</script></body></html>'''
html=html.replace('__ITEMS__',js(ITEMS)).replace('__FAC__',js(FAC)).replace('__META__',js(META))
(ROOT/'index.html').write_text(html,encoding='utf-8')
print('wrote',ROOT/'index.html',len(html))
